-- Window functions: ROWS/RANGE frames, partitioning, lag/lead, first/last value, ranking.
CREATE TABLE m (id int PRIMARY KEY, grp text NOT NULL, v int NOT NULL);
INSERT INTO m VALUES (1, 'a', 10), (2, 'a', 20), (3, 'a', 20), (4, 'b', 5), (5, 'b', 15), (6, 'b', 40), (7, 'c', 7);
SELECT id, sum(v) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS s FROM m ORDER BY id;
SELECT id, sum(v) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running FROM m ORDER BY id;
SELECT id, sum(v) OVER (PARTITION BY grp ORDER BY id ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS tail FROM m ORDER BY id;
SELECT id, sum(v) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) AS nearby FROM m ORDER BY id;
SELECT id, lag(v, 1, 0) OVER (PARTITION BY grp ORDER BY id) AS prev, lead(v, 1, -1) OVER (PARTITION BY grp ORDER BY id) AS next FROM m ORDER BY id;
SELECT id, first_value(v) OVER (PARTITION BY grp ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS fv, last_value(v) OVER (PARTITION BY grp ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS lv FROM m ORDER BY id;
SELECT id, rank() OVER (ORDER BY v) AS rk, dense_rank() OVER (ORDER BY v) AS drk, row_number() OVER (ORDER BY id) AS rn FROM m ORDER BY id;
